<script setup>
import {ref} from 'vue';
import ClinicalDiagnosisSearch from './ClinicalDiagnosisSearch.vue';
const props=defineProps({agencyId:[Number,String],clientId:[Number,String],sessionId:[Number,String],dateOfService:String,transport:Object,search:Function});
async function client(){return props.transport || (await import('../../services/api.js')).default;}
const emit=defineEmits(['saved']);
const query=ref(''),diagnosis=ref(null),provider=ref(''),justification=ref(''),documents=ref([]),selected=ref([]),attested=ref(false),error=ref(''),busy=ref(false);
async function load(){try{const {data}=await (await client()).get(props.transport?`/clients/${props.clientId}/diagnosis-evidence`:'/medical-billing/diagnoses/review',{params:{agencyId:props.agencyId,clientId:props.clientId},skipGlobalLoading:true});documents.value=data.documents || [];}catch(e){error.value=e.response?.data?.error?.message || 'Supporting records could not be loaded.';}}
async function save(){if(!diagnosis.value || !attested.value || !selected.value.length)return;busy.value=true;error.value='';try{const code=diagnosis.value.icd10_code || diagnosis.value.code;const recordedJustification=justification.value.trim()+'\nPreviously diagnosed by '+provider.value.trim()+'. Supporting professional documentation was reviewed and is in the client’s file.';const {data}=await (await client()).post(props.transport?`/sessions/${props.sessionId}/diagnoses`:'/medical-billing/diagnoses',{agencyId:props.agencyId,clientId:props.clientId,clinicalSessionId:props.sessionId,icd10Code:code,description:diagnosis.value.description,justification:recordedJustification,externalDiagnosis:{providerName:provider.value.trim(),evidenceDocumentIds:selected.value,attested:attested.value}},{skipGlobalLoading:true});emit('saved',{...diagnosis.value,id:data.id,icd10_code:code,justification:recordedJustification,source:'Outside professional diagnosis supported by uploaded records'});diagnosis.value=null;attested.value=false;}catch(e){error.value=e.response?.data?.error?.message || 'The outside diagnosis could not be recorded.';}finally{busy.value=false;}}
</script>
<template><details class="outside-diagnosis" @toggle="$event.target.open && load()"><summary>Record a diagnosis from another professional</summary><p>This records an established diagnosis from the client’s uploaded professional documentation.</p><ClinicalDiagnosisSearch v-model="query" :agency-id="agencyId" :date-of-service="dateOfService" :search="search" label="Diagnosis documented by the outside provider" @select="diagnosis=$event;attested=false" /><p v-if="diagnosis">{{diagnosis.icd10_code || diagnosis.code}} · {{diagnosis.description}}</p><label>Diagnosing professional<input v-model="provider" maxlength="300" /></label><label>Clinical justification and source summary<textarea v-model="justification" rows="3" /></label><label>Supporting documents in this client’s file<select v-model="selected" multiple><option v-for="document in documents" :key="document.id" :value="Number(document.id)">{{document.original_name || 'Document #'+document.id}}</option></select></label><label class="attest"><input v-model="attested" type="checkbox" /> I reviewed the selected professional documentation, confirm this diagnosis was made by the identified professional, and attest that the record accurately reflects that source.</label><p v-if="error" role="alert">{{error}}</p><button type="button" :disabled="busy || !attested || !selected.length || !diagnosis || provider.trim().length<3 || !justification.trim()" @click="save">{{busy?'Saving…':'Record verified outside diagnosis'}}</button></details></template>
<style scoped>.outside-diagnosis{font-size:13px;color:#284b63;border:1px solid #d1e0ea;border-radius:8px;padding:12px;margin-top:12px}.outside-diagnosis summary{font-weight:650;cursor:pointer}.outside-diagnosis p{font-size:12px;line-height:1.6}.outside-diagnosis label{display:block;margin:10px 0}.outside-diagnosis input:not([type=checkbox]),.outside-diagnosis textarea,.outside-diagnosis select{box-sizing:border-box;width:100%;display:block;font:inherit;line-height:1.6;border:1px solid #bcd0de;border-radius:7px;padding:8px;margin-top:5px}.outside-diagnosis .attest{display:flex;gap:8px;align-items:flex-start;line-height:1.5}.outside-diagnosis button{font:inherit;border:1px solid #b8cfde;background:#f4f8fc;color:#255676;border-radius:7px;padding:8px 12px}</style>
